float valeur = 15484.15115615; // On crée une variable qui a une donnée fixe et on va pouvoir l'appeler 
// Note : 'int' est pour les nombres entiers, pour les virgules on utilise 'float' ou 'double'
char i = 1;
char lettre = 'a'; // On crée une variable qui contient une lettre 

void setup() {
  Serial.begin(9600); // Ouvre le moniteur série 
  Serial.print("Salut, c'est Matteo"); // La carte envoie un message à notre PC
  Serial.println("Le prochain message est à la ligne"); // Envoie un message et ajoute un saut de ligne
  Serial.println("Coucou je suis en bas"); // Ce message sera à la ligne et le prochain aussi grâce au 'ln' 
  Serial.println(5); // Affiche un chiffre 
  Serial.println(458); // Affiche un nombre 
  Serial.println(44856.4586); // Affiche un nombre à virgule (par défaut, affiche 2 décimales)
  Serial.println(45.45856, 3); // Affiche 3 décimales après la virgule
  Serial.println(45.458568, 5); // Affiche 5 décimales (attention : arrondit le dernier chiffre affiché)
  Serial.println(valeur); // Affiche la donnée dans "valeur"
  Serial.println(lettre); // Affiche la donnée contenue dans "lettre" (ici 'a')
  Serial.println(65, BIN); // Affiche 65 en binaire
  Serial.println(65, DEC); // Affiche 65 en décimal 
  Serial.println(65, OCT); // Affiche 65 en octal
  Serial.println(65, HEX); // Affiche 65 en hexadécimal

  Serial.println("L'alphabet en entier :");
  for (i = 1; i < 27; i++) { // Correction syntaxe : i = 1
    Serial.print(lettre);
    lettre += 1; // Passe à la lettre suivante dans la table ASCII
    delay(250); 
  }
}

void loop() {
  // Vide car on ne veut exécuter le code qu'une seule fois au démarrage
}

